const response = await fetch('http://localhost:8000/v1/mcp/list');
const data = await response.json();
console.log(data);

const response = await fetch('http://localhost:8000/v1/mcp/install', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    name: 'GitHub MCP',
    url: 'http://localhost:8080',
    auth_token: 'ghp_123456789'
  })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/v1/mcp/install")
    .json(&serde_json::json!({
        "name": "GitHub MCP",
        "url": "http://localhost:8080",
        "auth_token": "ghp_123456789"
    }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

const response = await fetch('http://localhost:8000/v1/mcp/remove', {
  method: 'DELETE',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ mcp_id: 'mcp_gh' })
});
const data = await response.json();
console.log(data);

let client = reqwest::Client::new();
let res = client.delete("http://localhost:8000/v1/mcp/remove")
    .json(&serde_json::json!({ "mcp_id": "mcp_gh" }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

